try {
  const apps=$items('Get All Applications Data');
  const stats={};
  apps.forEach(item=>{
    const data=item.json;
    const source=data.source || 'Unknown';
    if(!stats[source]){
      stats[source]={total:0,interviewed:0,rejected:0,in_review:0,applied:0,avg_score:0,score_total:0,score_count:0};
    }
    const info=stats[source];
    info.total++;
    const status=(data.application_status||'').toLowerCase();
    if(status.includes('interview')) info.interviewed++;
    else if(status==='rejected') info.rejected++;
    else if(status==='in review' || status==='info requested') info.in_review++;
    else if(status==='applied') info.applied++;
    if(typeof data.ai_score==='number'){info.score_total+=data.ai_score;info.score_count++;}
  });
  Object.keys(stats).forEach(key=>{
    const info=stats[key];
    info.success_rate=info.total?((info.interviewed/info.total)*100).toFixed(1):'0.0';
    info.avg_score=info.score_count?(info.score_total/info.score_count).toFixed(1):'0.0';
  });
  return [{json:{source_analysis:stats,total_applications:apps.length}}];
} catch (error) {
  return [{json:{source_analysis:{},total_applications:0,error:error.message}}];
}

try {
  const apps=$items('Get All Applications Data');
  const roleData={};
  const regex=/\$([0-9,]+)(?:\s?-\s?\$?([0-9,]+))?/gi;
  apps.forEach(item=>{
    const text=((item.json.description||'')+' '+(item.json.title||'')).toLowerCase();
    const match=regex.exec(text);
    if(match){
      const category=item.json.title?.toLowerCase().includes('engineer')?'Engineering':'Other';
      if(!roleData[category]) roleData[category]={count:0,examples:[],avg_score:0,total_score:0};
      const info=roleData[category];
      info.count++;
      info.examples.push({company:item.json.company,title:item.json.title,salary:match[0]});
      if(typeof item.json.ai_score==='number'){info.total_score+=item.json.ai_score;}
    }
  });
  Object.keys(roleData).forEach(key=>{
    const d=roleData[key];
    d.avg_score=d.count?(d.total_score/d.count).toFixed(1):'0.0';
  });
  return [{json:{salary_trends:roleData,total_with_salary:Object.values(roleData).reduce((acc,c)=>acc+c.count,0)}}];
} catch(error){
  return [{json:{salary_trends:{},total_with_salary:0,error:error.message}}];
}

try {
  const apps=$items('Get All Applications Data');
  const keywords=['ai','machine learning','python','javascript','aws','azure','data'];
  const skills={};
  apps.forEach(item=>{
    const text=((item.json.description||'')+' '+(item.json.title||'')).toLowerCase();
    keywords.forEach(skill=>{
      if(text.includes(skill)){
        if(!skills[skill]) skills[skill]={count:0,high_score:0};
        skills[skill].count++;
        if((item.json.ai_score||0)>=8) skills[skill].high_score++;
      }
    });
  });
  const trending=Object.entries(skills).map(([skill,data])=>({skill,demand:((data.count/apps.length)||0)*100,high_score:data.high_score})).sort((a,b)=>b.demand-a.demand).slice(0,10);
  return [{json:{trending_skills:trending}}];
} catch(error){
  return [{json:{trending_skills:[],error:error.message}}];
}

