try {
  const source=$('Analyze Source Performance').item.json;
  const salary=$('Track Salary Trends').item.json;
  const skills=$('Analyze Skill Demand').item.json;
  const rec=$('Generate Strategic Recommendations').first().json.content || 'Recommendations unavailable.';
  const dashboard={
    generated_at:new Date().toISOString(),
    summary:{
      total_applications:source.total_applications || 0,
      active_sources:Object.keys(source.source_analysis||{}).length,
      salary_data_points:salary.total_with_salary || 0,
      trending_skills_count:(skills.trending_skills||[]).length
    },
    source_analysis:source.source_analysis || {},
    salary_trends:salary.salary_trends || {},
    skill_trends:skills.trending_skills || [],
    recommendations:rec
  };
  return [{json:{dashboard}}];
} catch(error){
  return [{json:{dashboard:{error:error.message}}}];
}

const dashboard=$('Create Dashboard Data').item.json.dashboard || { summary:{} };
const summary=dashboard.summary || {};
const report=`📊 Weekly Market Intelligence

Total Applications: ${summary.total_applications || 0}
Active Sources: ${summary.active_sources || 0}
Salary Data Points: ${summary.salary_data_points || 0}
Trending Skills: ${summary.trending_skills_count || 0}

Recommendations:
${dashboard.recommendations || 'Review data sources for insights.'}`;
return [{json:{report,dashboard}}];
